type Cell = [number, number];

const key = ([x, y]: Cell): string => `${x},${y}`;

function neighborsOf([x, y]: Cell): Cell[] {
  const result: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
    }
  }
  return result;
}

function countNeighbors(cell: Cell, cells: Cell[]): number {
  return cells.filter(
    ([x, y]) =>
      Math.abs(x - cell[0]) <= 1 &&
      Math.abs(y - cell[1]) <= 1 &&
      !(x === cell[0] && y === cell[1]),
  ).length;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  const survivors = cells.filter((cell) => {
    const count = countNeighbors(cell, cells);
    return count === 2 || count === 3;
  });
  const alive = new Set(cells.map(key));
  const candidates = new Map<string, Cell>();
  for (const cell of cells.flatMap(neighborsOf)) {
    if (!alive.has(key(cell))) candidates.set(key(cell), cell);
  }
  const births = [...candidates.values()].filter(
    (cell) => countNeighbors(cell, cells) === 3,
  );
  return [...survivors, ...births];
}
EOF
